  // calculated as a portion of the liquidated account value.
  updatedCollateral -= Math.min(
    availableAssets.percentToFraction(LIQUIDATION_INSURANCE_PREMIUM),
    updatedCollateral
  );

  return (updatedCollateral, executorPremium);
}
